from scipy.optimize import least_squares
import itertools
L=np.log(eps)
pool={'1':np.ones(300),'L':L,'1/e':1/eps,'1/e2':1/eps**2,'e':eps,'e2':eps**2,'sq':np.sqrt(eps),'1/sq':eps**-.5,'L2':L**2,'eL':eps*L,'T':T,'1/T':1/T}
def res(names,ab):
    A=np.c_[[pool[n] for n in names]+[eps**ab[0]*T**ab[1]]].T
    c=np.linalg.lstsq(A,sigma,rcond=None)[0]
    return A@c-sigma,c
